int tmp[n];
int boundary = 0;

// First group: elements satisfying predicate
for (int i = 0; i < n; i++) {
  if (predicate(arr[i])) {
    tmp[boundary++] = arr[i];
  }
}

// Second group: elements not satisfying predicate
for (int i = 0; i < n; i++) {
  if (!predicate(arr[i])) {
    tmp[boundary++] = arr[i];
  }
}

// Copy back into original array
for (int i = 0; i < n; i++) {
  arr[i] = tmp[i];
}
```

